import re
from openpyxl.utils import get_column_letter
s=open('xl/worksheets/sheet1.xml',encoding='utf-8').read()
cells = {}
for m in re.finditer(r'<c r="([A-Z]+)(\d+)"([^>]*)>(.*?)</c>', s, re.S):
    col=m.group(1); row=int(m.group(2)); attrs=m.group(3); inner=m.group(4)
    cells[(col,row)] = (attrs, inner)
# extract table of style ids for region A2:S83
styles={}
for r in range(2,84):
    for ci in range(1,20):
        col=get_column_letter(ci); key=(col,r)
        if key in cells:
            attrs,inner=cells[key]
            m=re.search(r's="(\d+)"', attrs)
            styles[key]=int(m.group(1)) if m else None
        else:
            styles[key]=None
# unique style combos per column
from collections import defaultdict
colstyles=defaultdict(set)
for (col,r),st in styles.items():
    colstyles[col].add(st)
for ci in range(1,20):
    col=get_column_letter(ci)
    print(col, sorted(colstyles[col]))
